/* Lot 103: color-mix() in the CSS Color 5 spaces with the hue methods (generated by scripts/lot103_gen.py; expectations from scripts/lot103_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[160];

static int syn(const char *s) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the reader colour of v as "#rrggbb alpha", "-" when it is not one */
static const char *rc(const char *v) {
    static char b[64];
    unsigned int c = 0xdeadbeefu;
    int a = -7, r = wf_cssprop_color(v, (int)strlen(v), &c, &a);
    if (!r) return c == 0xdeadbeefu && a == -7 ? "-" : "WRITTEN";
    if (r != 1 || c > 0xffffffu || a < 0 || a > 255) return "BAD CODE";
    snprintf(b, sizeof(b), "#%06x %d", c, a);
    return b;
}

